bool try_decode_s3_opcode1_t(uint8_t raw, uint8_t arch, S3Opcode1T* out) {
    if (arch < 9 || arch > 14) return false;
    uint32_t arch_bit = 1u << arch;
    switch (raw) {
        case 0:
            if (0x7e00u & arch_bit) { if (out) *out = S3Opcode1T::LD_CVT; return true; }
            return false;
        case 1:
            if (0x7e00u & arch_bit) { if (out) *out = S3Opcode1T::ST_CVT; return true; }
            return false;
        case 2:
            if (0x7000u & arch_bit) { if (out) *out = S3Opcode1T::LD_CHECKED_IMM; return true; }
            return false;
        case 3:
            if (0x7000u & arch_bit) { if (out) *out = S3Opcode1T::ST_CHECKED_IMM; return true; }
            return false;
        case 6:
            if (0x7e00u & arch_bit) { if (out) *out = S3Opcode1T::LD_ATTR; return true; }
            return false;
        case 7:
            if (0x7e00u & arch_bit) { if (out) *out = S3Opcode1T::LEA_ATTR; return true; }
            return false;
        case 8:
            if (0x7e00u & arch_bit) { if (out) *out = S3Opcode1T::LD_TILE; return true; }
            return false;
        case 9:
            if (0x7e00u & arch_bit) { if (out) *out = S3Opcode1T::ST_TILE; return true; }
            return false;
        case 13:
            if (0x7e00u & arch_bit) { if (out) *out = S3Opcode1T::ATEST; return true; }
            return false;
        case 14:
            if (0x7e00u & arch_bit) { if (out) *out = S3Opcode1T::ZS_EMIT; return true; }
            return false;
        case 15:
            if (0x7e00u & arch_bit) { if (out) *out = S3Opcode1T::BLEND; return true; }
            return false;
        default: return false;
    }
}

