    out->modifier_strs["memory_width"] = to_string(e_memory_width);
    out->fields["message_slot_index"] = f_message_slot_index;
    out->modifier_strs["message_slot_index"] = to_string(e_message_slot_index);
    out->fields["sr_count"] = f_sr_count;
    out->modifier_strs["sr_count"] = to_string(e_sr_count);
    out->fields["staging_register_index"] = f_staging_register_index;
    out->fields["staging_register_control_32"] = f_staging_register_control_32;
    out->modifier_strs["staging_register_control_32"] = to_string(e_staging_register_control_32);
