    oss << "." << to_string(e_message_slot_index);
    if (std::string(to_string(e_flow)) != "none") oss << "." << to_string(e_flow);
    oss << "." << to_string(e_atom_opc);
    bool first_arg = true;
    auto sep = [&]() { if (first_arg) { oss << " "; first_arg = false; } else { oss << ", "; } };
